#pragma once

/* Offline radar background, generated by tools/gen_map.py */

#include <stdint.h>

typedef struct {
    uint32_t start, count;              /* range in map_coast_pts */
    float lat_min, lat_max, lon_min, lon_max;  /* bounding box for culling */
} map_line_t;

typedef struct {
    uint8_t kind;                       /* 0 large, 1 medium, 2 small */
    char code[8];                       /* ICAO / local code */
    char iata[4];
    char name[40];
    float lat, lon;
} map_airport_t;

typedef struct {
    uint8_t kind;                       /* kind of the owning airport */
    uint16_t length_ft;
    float lat1, lon1, lat2, lon2;
} map_runway_t;

extern const float map_coast_pts[][2];
extern const map_line_t map_coast_lines[];
extern const int map_coast_line_count;
extern const char map_coast_credit[];   /* attribution to show on screen, may be empty */
extern const map_airport_t map_airports[];
extern const int map_airport_count;
extern const map_runway_t map_runways[];
extern const int map_runway_count;
